<?php $page_title = $product['name'] ?? 'Product'; require __DIR__ . '/../partials/shop_open.php';
$stock = max(0, (int)floor((float)($product['stock'] ?? 0)));
$layers = json_decode($product['layers'] ?? '[]', true);
?>
<main id="main" class="inner-page shell"><a class="text-link back-link" href="<?= url('?route=products') ?>">← Back to products</a>
<section class="product-detail"><div class="detail-photo"><img src="<?= $escape(get_product_image($product['image_url'] ?? '', $product['id'])) ?>" alt="<?= $escape($product['name']) ?>" width="900" height="1000" fetchpriority="high"></div><div class="detail-copy"><p class="eyebrow"><?= $escape($product['category_name'] ?? 'IN THE CATALOG') ?></p><h1><?= $escape($product['name']) ?></h1><p class="body-copy"><?= $escape($product['description'] ?? '') ?></p><div class="detail-price"><strong><?= $escape($currency) ?><?= number_format((float)$product['price'], 2) ?></strong><span class="availability <?= $stock > 0 ? '' : 'unavailable' ?>"><?= $stock > 0 ? 'Available' : 'Currently unavailable' ?></span></div>
<?php if ($stock > 0): ?><form class="quick-add detail-order" action="<?= url('?route=cart/add') ?>" method="post" data-unit-price="<?= (float)$product['price'] ?>" data-currency="<?= $escape($currency) ?>"><input type="hidden" name="csrf_token" value="<?= $escape(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label for="product-qty">Quantity</label><div class="quantity-picker"><button type="button" data-quantity-step="-1" aria-label="Decrease quantity">−</button><input id="product-qty" name="qty" type="number" min="1" max="<?= $stock ?>" value="1" step="1" required aria-label="Quantity"><button type="button" data-quantity-step="1" aria-label="Increase quantity">+</button></div><p class="quantity-hint">Up to <?= $stock ?> available.</p><div class="order-total"><span>Item total</span><strong data-item-total><?= $escape($currency) ?><?= number_format((float)$product['price'], 2) ?></strong></div><button class="button button-red" type="submit">Add to cart <span aria-hidden="true">+</span></button></form><?php else: ?><div class="shop-panel"><p>This item is unavailable right now. Take a look at the rest of the catalog.</p><a class="button button-red" href="<?= url('?route=products') ?>">Explore the catalog ↗</a></div><?php endif; ?>
<?php if (is_array($layers) && $layers): ?><details class="ingredient-details" open><summary>What’s inside</summary><ul><?php foreach ($layers as $layer): if (is_string($layer)): ?><li><?= $escape($layer) ?></li><?php endif; endforeach; ?></ul></details><?php endif; ?><div class="detail-links"><a class="text-link" href="<?= url('?route=cart') ?>">View your cart ↗</a><?php if (!empty($_SESSION['user']['id']) && User::has_permission($_SESSION['user']['id'], 'access_pos')): ?><a class="text-link" href="<?= url('?route=pos') ?>">Open staff POS ↗</a><?php endif; ?></div></div></section>
<?php $related = array_filter($related_products ?? [], $is_public_item); if ($related): ?><section class="related-section"><div class="section-heading"><div><p class="eyebrow">KEEP EXPLORING</p><h2>Something else to love.</h2></div></div><div class="product-grid"><?php foreach (array_slice($related, 0, 3) as $item) require __DIR__ . '/../partials/shop_product_card.php'; ?></div></section><?php endif; ?></main>
